import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·19","description":"易小帖 - 卷一·19","frontmatter":{"title":"卷一·19","description":"易小帖 - 卷一·19"},"headers":[],"relativePath":"zh/classics/yixiaotie/019.md","filePath":"zh/classics/yixiaotie/019.md"}'),o={name:"zh/classics/yixiaotie/019.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·19",tabindex:"-1"},[r("卷一·19 "),e("a",{class:"header-anchor",href:"#卷一·19","aria-label":"Permalink to “卷一·19”"},"​")],-1),e("p",null,"何以守位曰仁，何以聚人曰財。言以顯仁守位，以富有聚人也。顯仁富有，皆《大傳》中原文。自朱註引陸氏《釋文》，改仁為人，致元吳澄，明季本，競起改竄，而作偽古本，且謂古本如是，可畏極矣。盧東元作此辯雲：經文無義者，或改正之。如井有仁焉，吉之先見是也。有義者不宜輕改此類是也。夫仁者天地之大德也，天子守位曰仁，足矣，何必改從人乎。武王有臣三千，惟一心仁也。紂有臣億萬人，惟億萬心，不仁也。仁則寇戎為父子，不仁則赤子為仇讎。故《大學》曰：有德此有人。蔡邕曰：仁以守位。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
